Master:
try {

$ErrorActionPreference='Stop'
Set-Location -LiteralPath 'F:\.codex\worktrees\ecs-relations-worker-3\SomeEngine.Next'
$sourceRecord=Get-Content -LiteralPath 'artifacts/relations-measurements/focused-native-r42/source.json' -Raw|ConvertFrom-Json
$source=[string]$sourceRecord.SourceCommit
if($sourceRecord.PublishExitCode -ne 0 -or $sourceRecord.SourceCheckExitCode -ne 0){exit 4}
$control='artifacts/relations-measurements/focused-native-r42'
$series='focused-native-r42'
$publish=Get-Content -LiteralPath 'artifacts/benchmark-queue/734696c3200a437bb1f61a2b09f541b9/result.json' -Raw|ConvertFrom-Json
Write-Output ('PUBLISH_GATE '+$publish.Id+' ExitCode='+$publish.ExitCode+' FinishedAtUtc='+$publish.FinishedAtUtc)
if($publish.ExitCode -ne 0){exit 2}
$reader=Get-Content -LiteralPath 'artifacts/benchmark-queue/16edbce2c6204e5280e7021ed442d137/result.json' -Raw|ConvertFrom-Json
if($reader.ExitCode -ne 0){exit 5}
git diff --exit-code $source -- 'src/**/*.cs' 'benchmarks/**/*.cs' 'tests/**/*.cs'
if($LASTEXITCODE -ne 0){exit 3}
$rootRecord=[pscustomobject]@{SourceCommit=$source;RootHostReadEndedAtUtc='2026-10-20T00:02:00Z';StandardsReadEndedAtUtc='2026-10-20T00:02:28Z';RecordedAtUtc=[DateTime]::UtcNow.ToString('O')}
$rootTemporary=Join-Path $control 'root-host-released.json.tmp'
[IO.File]::WriteAllText($rootTemporary,($rootRecord|ConvertTo-Json))
[IO.File]::Move($rootTemporary,(Join-Path $control 'root-host-released.json'),$true)
$started=[DateTime]::UtcNow
& './benchmarks/SomeEngine.ECS.Relations.Benchmarks/Submit-Measurements.ps1' -Series $series -CaseId @('threads-small-sparse-parallel','threads-small-uniform-parallel') -Backend NativeAOT -Mode measure -Machine Fixed -QueueScript 'F:\SomeEngine.Next\tools\Invoke-Benchmark.ps1' -Session '01a15090-f5bd-7a12-860a-e214325db5bb' -CollectReports -SourceCommit $source
$reportRoot=[IO.Path]::GetFullPath('artifacts/ecs-relations/measurements/focused-native-r42')
$submissions=Get-Content -LiteralPath (Join-Path $reportRoot 'submissions.json') -Raw|ConvertFrom-Json
$queueSubmission=Get-Content -LiteralPath (Join-Path $reportRoot 'queue-submission.json') -Raw|ConvertFrom-Json
$manifest=[pscustomobject]@{SourceCommit=$source;Submissions=(Join-Path $reportRoot 'submissions.json');QueueSubmission=(Join-Path $reportRoot 'queue-submission.json');CaseQueueIds=@($submissions.QueueId);AnalysisQueueIds=@($queueSubmission.Reports.QueueId);SubmissionFinishedAtUtc=$queueSubmission.FinishedAtUtc}
$temporary=Join-Path $control 'manifest-ready.json.tmp'
[IO.File]::WriteAllText($temporary,($manifest|ConvertTo-Json -Depth 5))
[IO.File]::Move($temporary,(Join-Path $control 'manifest-ready.json'),$true)
while(!(Test-Path -LiteralPath (Join-Path $control 'watcher-ready.json')) -or !(Test-Path -LiteralPath (Join-Path $control 'native-reader-released.json')) -or !(Test-Path -LiteralPath (Join-Path $control 'root-host-released.json'))){Start-Sleep -Milliseconds 20}
$ready=Get-Content -LiteralPath (Join-Path $control 'watcher-ready.json') -Raw|ConvertFrom-Json
$readerRelease=Get-Content -LiteralPath (Join-Path $control 'native-reader-released.json') -Raw|ConvertFrom-Json
$rootRelease=Get-Content -LiteralPath (Join-Path $control 'root-host-released.json') -Raw|ConvertFrom-Json
if($rootRelease.SourceCommit -ne $source){exit 7}
if($readerRelease.ReaderQueueId -ne $reader.Id -or $readerRelease.SourceCommit -ne $source){exit 6}
$finished=[DateTime]::UtcNow
$record=[pscustomobject]@{SourceCommit=$source;PublishQueueId=$publish.Id;StartedAtUtc=$started;LastCaseSubmittedAtUtc=$queueSubmission.FinishedAtUtc;InitialObservationEndedAtUtc=$finished;WatcherInitialObservationEndedAtUtc=$ready.InitialObservationEndedAtUtc;NativeReaderRelease=$readerRelease;RootHostRelease=$rootRelease;PreparationEndAtUtc=$finished;CaseCount=$submissions.Count;ReaderQueueId=$reader.Id;FinalQueueId=$ready.FinalQueueId}
$record|ConvertTo-Json -Depth 5|Set-Content -LiteralPath (Join-Path $control 'preparation.json') -Encoding utf8
Write-Output ('PREPARATION_END '+($record|ConvertTo-Json -Compress))
exit 0

} finally { Remove-Item -LiteralPath $PSCommandPath }

Watcher:
$ErrorActionPreference='Stop'
$taskRoot='F:\.codex\worktrees\ecs-relations-worker-3\SomeEngine.Next'
$control=Join-Path $taskRoot 'artifacts\relations-measurements\focused-native-r42'
New-Item -ItemType Directory -Path $control -Force|Out-Null
$manifestPath=Join-Path $control 'manifest-ready.json'
$masterPath=Join-Path $control 'master-submission.json'
$queueRoot=Join-Path $taskRoot 'artifacts\benchmark-queue'
$watcher=[IO.FileSystemWatcher]::new((Join-Path $taskRoot 'artifacts'),'*.json')
$watcher.IncludeSubdirectories=$true
$watcher.NotifyFilter=[IO.NotifyFilters]::FileName
$watcher.EnableRaisingEvents=$true
$started=[pscustomobject]@{ProcessId=$PID;ProcessStartedAtUtc=(Get-Process -Id $PID).StartTime.ToUniversalTime();WatchReadyAtUtc=[DateTime]::UtcNow}
$started|ConvertTo-Json|Set-Content -LiteralPath (Join-Path $control 'watch-started.json') -Encoding utf8
Write-Output ('WATCH_READY '+($started|ConvertTo-Json -Compress))
try {
    $master=$null
    while(!(Test-Path -LiteralPath $manifestPath) -or !(Test-Path -LiteralPath $masterPath)) {
        if(!$master -and (Test-Path -LiteralPath $masterPath)) {
            $master=Get-Content -LiteralPath $masterPath -Raw|ConvertFrom-Json
        }
        if($master -and (Test-Path -LiteralPath (Join-Path $master.OutputDirectory 'result.json')) -and !(Test-Path -LiteralPath $manifestPath)) {
            Write-Output ('MASTER_RECEIPT_BEFORE_MANIFEST '+[DateTime]::UtcNow.ToString('o'))
            exit 2
        }
        $change=$watcher.WaitForChanged([IO.WatcherChangeTypes]::All,50000)
    }
    $initialStarted=[DateTime]::UtcNow
    $manifest=Get-Content -LiteralPath $manifestPath -Raw|ConvertFrom-Json
    $master=Get-Content -LiteralPath $masterPath -Raw|ConvertFrom-Json
    $ids=[Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
    foreach($id in $manifest.CaseQueueIds){$null=$ids.Add([string]$id)}
    if($ids.Count -ne 2 -or $ids.Contains('')){throw 'The manifest must contain 2 unique case queue ids.'}
    $seen=[Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
    $finalId=[string]$manifest.AnalysisQueueIds[-1]
    $finalPath=Join-Path $queueRoot ($finalId+'\result.json')
    $ready=[pscustomobject]@{
        ProcessId=$PID;SourceCommit=$manifest.SourceCommit
        InitialObservationStartedAtUtc=$initialStarted;InitialObservationEndedAtUtc=[DateTime]::UtcNow
        CaseQueueIds=@($manifest.CaseQueueIds);AnalysisQueueIds=@($manifest.AnalysisQueueIds)
        FinalQueueId=$finalId;FinalReceipt=$finalPath
    }
    $temporary=Join-Path $control 'watcher-ready.json.tmp'
    [IO.File]::WriteAllText($temporary,($ready|ConvertTo-Json -Depth 5))
    [IO.File]::Move($temporary,(Join-Path $control 'watcher-ready.json'),$true)
    Write-Output ('INITIAL_OBSERVATION_END '+($ready|ConvertTo-Json -Depth 5 -Compress))
    while(!(Test-Path -LiteralPath $finalPath)) {
        $change=$watcher.WaitForChanged([IO.WatcherChangeTypes]::All,50000)
        if($change.Name -and [IO.Path]::GetFileName($change.Name) -eq 'result.json') {
            $caseQueueId=[IO.Path]::GetFileName([IO.Path]::GetDirectoryName($change.Name))
            if($ids.Contains($caseQueueId) -and $seen.Add($caseQueueId)) {
                Write-Output ('CASE_RECEIPT '+$seen.Count+'/'+$ids.Count+' '+$caseQueueId+' '+[DateTime]::UtcNow.ToString('o'))
            }
        }
    }
    $finished=[pscustomobject]@{FinalQueueId=$finalId;ObservedAtUtc=[DateTime]::UtcNow;CaseReceiptsObserved=$seen.Count}
    $finished|ConvertTo-Json|Set-Content -LiteralPath (Join-Path $control 'final-observed.json') -Encoding utf8
    Write-Output ('FINAL_RECEIPT '+($finished|ConvertTo-Json -Compress))
}
finally{$watcher.Dispose();Remove-Item -LiteralPath $PSCommandPath}
